"use strict";function submitForm(n){$("#IsExportExcel").val(n)}function query(n){const t=window.location.search;t&&n&&initDataFirstQuery(t);const i=$(".card-container-base form").serialize(),r=_global.root+"JobGrade/GetJobGrades?"+i;if(!n){const n=_global.root+"JobGrade/Index?"+i;window.history.replaceState(null,null,n)}$.ajax({url:r,dataType:"html",method:"GET",beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#list-data").html(n);$("table#data").length>0&&$("table#data").addClass("table-success");floatThead("table#data")},error:function(n,t,i){alert(t+": "+i)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function initDataFirstQuery(n){const t=new URLSearchParams(n),i=t.get("TeamId"),r=t.get("Employee"),u=t.get("EmployeeId");$("#TeamId").val(i);$("#Employee").val(r);$("#EmployeeId").val(u)}$(document).ready(function(){initAutocomplete("#Employee","#EmployeeId",!1);$("form").submit(function(){var n=$("#Employee").val();return n.length===0&&$("#EmployeeId").val(-1),!0})});$(document).ready(function(){query(!0);$("#submit").on("click",function(){query(!1)})});